source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    separators = [(r, row[0]) for r, row in enumerate(grid) if row[0] != 0 and all(v == row[0] for v in row)]
    if not separators:
        return out
    frame = separators[0][1]
    sep_rows = [r for r, _ in separators]
    bands = []
    start = 0
    for sep in sep_rows:
        if start < sep:
            bands.append((start, sep))
        start = sep + 1
    if start < h:
        bands.append((start, h))

    for (a0, a1), (b0, b1) in zip(bands, bands[1:]):
        if a1 != b0 - 1 or a1 >= h or grid[a1][0] != frame:
            continue
        colors_a = {v for row in grid[a0:a1] for v in row if v not in (0, frame)}
        colors_b = {v for row in grid[b0:b1] for v in row if v not in (0, frame)}
        common = colors_a & colors_b
        if not common or a1 - a0 != b1 - b0:
            continue
        n = a1 - a0
        for r in range(n):
            for c in range(w):
                v = grid[a0 + r][c]
                if v in common:
                    rr = b0 + (n - 1 - r)
                    if out[rr][c] in (0, v):
                        out[rr][c] = v
                v = grid[b0 + r][c]
                if v in common:
                    rr = a0 + (n - 1 - r)
                    if out[rr][c] in (0, v):
                        out[rr][c] = v
    return out
'''
